exploreUrl:
@js:
var result = [];
java.toast("🔥正在刷新列表,请稍等！");
var push = (title, url, size) => result.push({
    "title": title,
    "url": url,
    "style": {
        "layout_flexGrow": 1,
        "layout_flexBasisPercent": size
    }
});
var baseUrl = "http://www.60ksw.com/bookstore/";
var tag = java.ajax(baseUrl);
if (tag) {
    var a = org.jsoup.Jsoup.parse(tag).select(".class_list a");
    push("🔥分类小说🔥", null, 1);
    for (var i = 0; i < a.length -2; i++) {
        var title = a[i].text();
        var url = a[i].attr("href");
        var size = 0.25;
        title = String(title).replace(/\s/g, "");
        url = String(url).replace(/-1\./,'-{{page}}.');      
        push(title, url, size);
        if (i == 10 && a.length > 10) {
            push("🔥字数🔥", null, 1);
        }
        if (i == 16 && a.length > 16) {
            push("🔥进度🔥", null, 1);
        }
        if (i == 19 && a.length > 19) {
            push("🔥榜单🔥", null, 1);
        }
        if (i == 32 && a.length > 32) {
            push("🔥字母🔥", null, 1);
        }
    }
} else {
  java.toast("🤔列表刷新失败！！！");     
} 
JSON.stringify(result);
